  isIdentifier,
  isImportDeclaration,
  isNamedExports,
  isNamedImports,
  isNumericLiteral,
  isObjectLiteralExpression,
  isParenthesizedExpression,
  isPropertyAccessExpression,
  isPropertyAssignment,
  isSatisfiesExpression,
  isSpreadAssignment,
  isStringLiteralLikeNode,
  isVariableStatement,
  NodeFlags,
  SyntaxKind,
